// Join Family by code + Head's Join Requests review. docs/Three_Portal_Feature_Spec.md.
import { type FormEvent, useCallback, useEffect, useState } from 'react'

import { EmptyState, ErrorState, LoadingState } from '../../components/shared/ViewState'
import { useAppSelector } from '../../store/hooks'
import { apiClient, threePortalApi, type FamilyDto, type JoinRequestDto } from '../../services/apiClient'
import { IncomingInvitationsPanel } from './IncomingInvitationsPanel'
import { FriendlyStatusBadge } from './threePortalShared'
import { extractErrorMessage, formatDateTime } from './threePortalUtils'

export function JoinFamilyPage() {
  const user = useAppSelector((state) => state.auth.user)
  const isHead = user?.role === 'FAMILY_HEAD'

  const [tab, setTab] = useState<'join' | 'requests'>(isHead ? 'requests' : 'join')
  const [myRequests, setMyRequests] = useState<JoinRequestDto[]>([])
  const [pendingRequests, setPendingRequests] = useState<JoinRequestDto[]>([])
  const [status, setStatus] = useState<'loading' | 'ready' | 'error'>('loading')
  const [message, setMessage] = useState('')

  const load = useCallback(async () => {
    setStatus('loading')
    try {
      if (isHead) {
        const { data: family } = await apiClient.get<FamilyDto>('/families/me')
        const { data } = await threePortalApi.getFamilyJoinRequests(family.id, 'Pending')
        setPendingRequests(data)
      } else {
        const { data } = await threePortalApi.getMyJoinRequests()
        setMyRequests(data)
      }
      setStatus('ready')
    } catch {
      setStatus('error')
    }
  }, [isHead])

  useEffect(() => {
    void load()
  }, [load])

  async function submitJoin(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = new FormData(event.currentTarget)
    const familyCode = String(form.get('familyCode') || '').trim().toUpperCase()
    const relationshipType = String(form.get('relationshipType') || '').trim()
    const requestMessage = String(form.get('message') || '').trim() || undefined
    setMessage('')
    try {
      await threePortalApi.submitJoinRequest({ familyCode, relationshipType, message: requestMessage })
      event.currentTarget.reset()
      setMessage('Join request sent. The family head will review it.')
      await load()
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Join request could not be sent. Check the family code and try again.'))
    }
  }

  async function accept(request: JoinRequestDto) {
    try {
      await threePortalApi.acceptJoinRequest(request.id)
      setMessage(`${request.requesterDisplayName} added to your family.`)
      await load()
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Request could not be accepted.'))
    }
  }

  async function decline(request: JoinRequestDto) {
    try {
      await threePortalApi.declineJoinRequest(request.id)
      setMessage(`Request from ${request.requesterDisplayName} declined.`)
      await load()
    } catch (error) {
      setMessage(extractErrorMessage(error, 'Request could not be declined.'))
    }
  }

  return (
    <div className="page-stack">
      <header className="page-header">
        <div>
          <p className="eyebrow">Family membership</p>
          <h1>{isHead ? 'Join requests' : 'Join a family'}</h1>
        </div>
      </header>

      {isHead && (
        <div className="tab-bar" role="tablist">
          <button type="button" role="tab" aria-selected={tab === 'requests'} className={tab === 'requests' ? 'active' : ''} onClick={() => setTab('requests')}>
            Join requests
          </button>
          <button type="button" role="tab" aria-selected={tab === 'join'} className={tab === 'join' ? 'active' : ''} onClick={() => setTab('join')}>
            Join another family
          </button>
        </div>
      )}

      {message && <p role="status" className="status-banner">{message}</p>}

      <IncomingInvitationsPanel onChanged={load} onMessage={setMessage} />

      {tab === 'join' && (
        <section className="panel">
          <h2>Join a family by code</h2>
          <form className="form-grid" onSubmit={(event) => void submitJoin(event)}>
            <label>
              Family code
              <input name="familyCode" required minLength={9} maxLength={9} placeholder="FV-XXXXXX" />
            </label>
            <label>
              Your relationship
              <input name="relationshipType" required maxLength={40} placeholder="e.g. spouse, sibling" />
            </label>
            <label>
              Message (optional)
              <textarea name="message" maxLength={280} />
            </label>
            <button className="button button--primary" type="submit">Send join request</button>
          </form>

          <h3>My requests</h3>
          {status === 'loading' ? (
            <LoadingState label="Loading your join requests" />
          ) : status === 'error' ? (
            <ErrorState message="Could not load your join requests." onRetry={() => void load()} />
          ) : myRequests.length === 0 ? (
            <EmptyState title="No requests yet" message="Requests you send will appear here." />
          ) : (
            <ul className="activity-list">
              {myRequests.map((request) => (
                <li key={request.id}>
                  <span>
                    {request.familyName} · {request.relationshipType}
                  </span>
                  <FriendlyStatusBadge status={request.status} />
                  <small>{formatDateTime(request.createdAt)}</small>
                </li>
              ))}
            </ul>
          )}
        </section>
      )}

      {isHead && tab === 'requests' && (
        <section className="panel">
          <h2>Pending join requests</h2>
          {status === 'loading' ? (
            <LoadingState label="Loading join requests" />
          ) : status === 'error' ? (
            <ErrorState message="Could not load join requests." onRetry={() => void load()} />
          ) : pendingRequests.length === 0 ? (
            <EmptyState title="No pending requests" message="Nobody is waiting to join your family right now." />
          ) : (
            <div className="table-scroll">
              <table>
                <thead>
                  <tr>
                    <th>Requester</th>
                    <th>Relationship</th>
                    <th>Message</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {pendingRequests.map((request) => (
                    <tr key={request.id}>
                      <td>{request.requesterDisplayName} <small className="muted">{request.requesterEmailMasked}</small></td>
                      <td>{request.relationshipType}</td>
                      <td>{request.message || '—'}</td>
                      <td>
                        <button className="button button--primary" type="button" onClick={() => void accept(request)}>Accept</button>{' '}
                        <button className="button button--secondary" type="button" onClick={() => void decline(request)}>Decline</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </section>
      )}
    </div>
  )
}
